function kSmallest(nums, k) {
  const heap = new Heap((a, b) => b - a);    // a max-heap of the k smallest so far
  for (const x of nums) {
    heap.push(x);
    if (heap.size() > k) heap.pop();         // drop the largest: it can't be among the k smallest
  }
  const out = [];
  while (heap.size() > 0) out.push(heap.pop());
  return out.reverse();                      // smallest first
}

import heapq

def k_smallest(nums, k):
    heap = []                                # holds -x: a max-heap of the k smallest so far
    for x in nums:
        heapq.heappush(heap, -x)
        if len(heap) > k:
            heapq.heappop(heap)              # drop the largest: it can't be among the k smallest
    return sorted(-x for x in heap)          # smallest first

List<Integer> kSmallest(int[] nums, int k) {
    PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());   // max-heap
    for (int x : nums) {
        heap.offer(x);
        if (heap.size() > k) heap.poll();    // drop the largest: it can't be among the k smallest
    }
    List<Integer> out = new ArrayList<>();
    while (!heap.isEmpty()) out.add(heap.poll());
    Collections.reverse(out);                // smallest first
    return out;
}

vector<int> kSmallest(const vector<int>& nums, int k) {
    priority_queue<int> heap;                // a max-heap of the k smallest so far
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();   // drop the largest: it can't be among the k smallest
    }
    vector<int> out;
    while (!heap.empty()) {
        out.push_back(heap.top());
        heap.pop();
    }
    reverse(out.begin(), out.end());         // smallest first
    return out;
}
